/**
 * @zakkster/lite-leak kernel: emitter-orphan
 *
 * Detects Node `EventEmitter` listeners that outlive the owner that added them.
 *
 * An emitter holds its listeners with a strong reference, and a listener holds
 * everything its closure captures. Add one to a long-lived emitter --
 * `process`, a shared bus, a socket server -- inside a component, forget to
 * remove it on teardown, and every mount leaks the listener plus its captured
 * scope. The process gets slower and heavier the longer it runs, and a heap
 * snapshot shows a growing listener array on an emitter that is *supposed* to be
 * long-lived, which reads as normal.
 *
 * Node already warns here, but crudely: `MaxListenersExceededWarning` fires at a
 * fixed count (default 10) with no notion of ownership, so it is silent on a
 * genuine leak below the threshold and noisy on a legitimate emitter with many
 * listeners. This kernel classifies by ownership instead -- a listener added
 * inside an effect/computed body, whose owner has since been disposed, while the
 * listener is still attached.
 *
 * `EventEmitter` is REQUIRED, not defaulted: there is no `globalThis.EventEmitter`,
 * and silently defaulting to nothing would install a kernel that patches nothing
 * and reports clean forever. Pass it explicitly:
 *
 *   import { EventEmitter } from 'node:events';
 *   createEmitterOrphanKernel({ EventEmitter });
 *
 * **`warnOnNoOwner` defaults to false here, unlike every browser kernel.** In a
 * browser, a resource created outside any owner is worth a warning. In Node,
 * the runtime itself -- streams, timers, the process object -- adds listeners
 * outside any lite-signal owner constantly, so warning on every ownerless add
 * would bury the signal. The owner-disposed case is the one that is actionable,
 * and it is always reported.
 *
 * Not covered: `once`/`prependOnceListener`. A once-listener that fires
 * auto-removes and is not a leak; one that never fires is a smaller, separate
 * class this kernel does not classify, so it is left out rather than reported
 * imprecisely.
 *
 * Patch surfaces: 'on', 'addListener', 'prependListener' (adds);
 * 'removeListener', 'off' (reaps).
 *
 * In-house consumer: `@zakkster/lite-ws` (its Node server path).
 *
 * Copyright (c) 2026 Zahary Shinikchiev <shinikchiev@yahoo.com>
 * MIT License
 */

import { getOwner, onCleanup, nodeId } from '@zakkster/lite-signal';
import { _claimPatchSurface, _releasePatchSurface, _restoreIfOurs } from '../Leak.js';

const KIND = 'emitter-orphan';
const EMPTY_OPTIONS = Object.freeze(Object.create(null));

// on/addListener are the same function in Node, as are off/removeListener; each
// name is claimed and patched independently so a partial environment (only some
// present) still works and restoration is exact.
const ADD_SURFACES = ['on', 'addListener', 'prependListener'];
const REMOVE_SURFACES = ['removeListener', 'off'];

/**
 * Create the emitter-orphan kernel.
 *
 * @param {object} options
 * @param {Function} options.EventEmitter
 *   The `EventEmitter` class whose prototype is instrumented. Required.
 * @param {boolean} [options.warnOnNoOwner=false]
 *   Emit a warning when a listener is added outside any owner. Off by default:
 *   ownerless adds are the norm in Node and warning on them is noise.
 * @param {boolean} [options.captureStacks=false]
 * @param {number} [options.priority=0]
 */
export function createEmitterOrphanKernel(options) {
  const opts = options || EMPTY_OPTIONS;
  const EE = opts.EventEmitter;
  if (typeof EE !== 'function' || EE.prototype === null || typeof EE.prototype !== 'object') {
    throw new TypeError(
      'createEmitterOrphanKernel: options.EventEmitter is required and must be the ' +
      'EventEmitter class (import { EventEmitter } from "node:events")'
    );
  }
  const proto = EE.prototype;
  const warnOnNoOwner = opts.warnOnNoOwner === true;   // opt-IN, unlike browser kernels
  const captureStacks = opts.captureStacks === true;
  const priority = typeof opts.priority === 'number' ? opts.priority : 0;

  let ctx = null;
  let originals = null;
  let ours = null;
  let claimed = null;

  // Every tracked (emitter, event, listener) triple. WeakRefs on both ends, so
  // the kernel never pins an emitter or a listener it is only watching.
  const records = new Set();
  // emitter -> Set<record>, for O(1)-ish reap lookup on removeListener.
  const byEmitter = new WeakMap();

  /** @private */
  function addRecord(emitter, event, listener, ownerHandle, origin) {
    const record = {
      emitterRef: new WeakRef(emitter),
      listenerRef: new WeakRef(listener),
      event: event,
      ownerHandle: ownerHandle,
      origin: origin,
      reaped: false,
    };
    records.add(record);
    let set = byEmitter.get(emitter);
    if (set === undefined) { set = new Set(); byEmitter.set(emitter, set); }
    set.add(record);
    return record;
  }

  /** @private Drop the record matching (emitter, event, listener), if any. */
  function reapRecord(emitter, event, listener) {
    const set = byEmitter.get(emitter);
    if (set === undefined) return;
    for (const record of set) {
      if (record.event !== event) continue;
      if (record.listenerRef.deref() !== listener) continue;
      record.reaped = true;
      records.delete(record);
      set.delete(record);
      return;
    }
  }

  /** @private A listener is only a leak while it is still attached. */
  function stillAttached(emitter, event, listener) {
    if (typeof emitter.listeners !== 'function') return true;   // cannot tell; assume yes
    const arr = emitter.listeners(event);
    for (let i = 0; i < arr.length; i++) {
      // Node stores the user function directly for on()/addListener().
      if (arr[i] === listener) return true;
    }
    return false;
  }

  /** @private Build a patched add method sharing the tracking logic. */
  function makePatchedAdd(orig) {
    return function patchedAdd(event, listener) {
      const result = orig.apply(this, arguments);
      if (ctx === null) return result;               // uninstalled mid-call
      if (typeof listener !== 'function') return result;
      // once()/prependOnceListener() call on()/prependListener() internally with
      // a wrapper carrying a `.listener` back-reference. Skip those: a fired
      // once-listener auto-removes (not a leak), and `listeners()` unwraps it,
      // so tracking the wrapper would misread attachment. Documented non-goal.
      if (typeof listener.listener === 'function') return result;

      const emitter = this;
      const ownerHandle = getOwner();
      const origin = captureStacks ? new Error().stack : null;

      // Track for the FR-refine path. The tag carries only primitives; emitter
      // and listener are already mutually retained, so this adds no retention.
      const handle = ctx.track(listener, function () {}, {
        kind: 'emitter-listener',
        event: typeof event === 'string' ? event : String(event),
        origin: origin,
      }, { audit: false });

      const record = addRecord(emitter, event, listener, ownerHandle, origin);

      if (ownerHandle !== undefined) {
        onCleanup(function () {
          if (ctx !== null) ctx.untrack(handle);
          // Honour the owner's intent: remove the listener it added.
          if (originals !== null && typeof emitter.removeListener === 'function') {
            try { emitter.removeListener(event, listener); } catch (_e) { /* subclass quirk */ }
          }
          // If removal worked, drop the record. If the listener is STILL
          // attached (broken removeListener, wrong event name, re-added
          // elsewhere), keep it: the owner is now disposed and audit will report
          // owner-disposed-listener-live -- a leak the cleanup failed to fix.
          if (!stillAttached(emitter, event, listener)) {
            record.reaped = true;
            records.delete(record);
            const set = byEmitter.get(emitter);
            if (set !== undefined) set.delete(record);
          }
        });
      } else if (warnOnNoOwner) {
        ctx.emitWarning({
          kind: KIND,
          reason: 'no-owner-add',
          event: typeof event === 'string' ? event : String(event),
          origin: origin,
        });
      }
      return result;
    };
  }

  /** @private A remove method that drops our record so a removed listener is not reported. */
  function makePatchedRemove(orig) {
    return function patchedRemove(event, listener) {
      if (ctx !== null && typeof listener === 'function') {
        reapRecord(this, event, listener);
      }
      return orig.apply(this, arguments);
    };
  }

  const kernel = {
    name: 'emitter-orphan',
    patchSurfaces: ADD_SURFACES.concat(REMOVE_SURFACES),
    priority: priority,

    install(kernelCtx) {
      ctx = kernelCtx;
      originals = {};
      ours = {};
      claimed = [];
      let contested = null;

      for (const name of ADD_SURFACES) {
        const orig = proto[name];
        if (typeof orig !== 'function') continue;
        if (_claimPatchSurface(proto, name)) claimed.push(name);
        else { if (contested === null) contested = []; contested.push(name); }
        originals[name] = orig;
        ours[name] = makePatchedAdd(orig);
        proto[name] = ours[name];
      }
      for (const name of REMOVE_SURFACES) {
        const orig = proto[name];
        if (typeof orig !== 'function') continue;
        if (_claimPatchSurface(proto, name)) claimed.push(name);
        else { if (contested === null) contested = []; contested.push(name); }
        originals[name] = orig;
        ours[name] = makePatchedRemove(orig);
        proto[name] = ours[name];
      }

      if (contested !== null) {
        ctx.emitFinding({
          kind: KIND,
          reason: 'patch-double-install',
          surfaces: contested,
          detail: 'EventEmitter.prototype already patched by another lite-leak kernel ' +
            'instance; listeners would be counted twice',
        });
      }
    },

    uninstall() {
      if (originals === null) return;
      let clobbered = null;
      for (const name of ADD_SURFACES.concat(REMOVE_SURFACES)) {
        if (typeof originals[name] !== 'function') continue;
        if (!_restoreIfOurs(proto, name, ours[name], originals[name])) {
          if (clobbered === null) clobbered = [];
          clobbered.push(name);
        }
      }
      if (clobbered !== null && ctx !== null) {
        ctx.emitFinding({
          kind: KIND,
          reason: 'patch-layered',
          surfaces: clobbered,
          detail: 'another wrapper was installed over these after this kernel; left in place',
        });
      }
      if (claimed !== null) {
        for (const name of claimed) _releasePatchSurface(proto, name);
        claimed = null;
      }
      originals = null;
      ours = null;
      records.clear();
      ctx = null;
    },

    refine(report, leakRecord) {
      const tag = leakRecord.tag;
      if (tag === null || typeof tag !== 'object') return null;
      if (tag.kind !== 'emitter-listener') return null;
      return {
        tag: report.tag,
        ownerPath: report.ownerPath,
        origin: report.origin,
        kind: KIND,
        collectedAt: report.collectedAt,
        event: tag.event,
      };
    },

    audit() {
      if (ctx === null) return [];
      const findings = [];
      let dead = null;

      for (const record of records) {
        if (record.reaped) continue;
        const emitter = record.emitterRef.deref();
        const listener = record.listenerRef.deref();
        // Either end collected -> nothing is retained -> not a leak.
        if (emitter === undefined || listener === undefined) {
          if (dead === null) dead = [];
          dead.push(record);
          continue;
        }
        // Removed since -> not a leak.
        if (!stillAttached(emitter, record.event, listener)) {
          if (dead === null) dead = [];
          dead.push(record);
          continue;
        }
        if (record.ownerHandle !== undefined && record.ownerHandle !== null) {
          if (nodeId(record.ownerHandle) === undefined) {
            findings.push({
              kind: KIND,
              reason: 'owner-disposed-listener-live',
              event: typeof record.event === 'string' ? record.event : String(record.event),
              origin: record.origin,
            });
          }
        }
      }

      if (dead !== null) {
        for (let i = 0; i < dead.length; i++) {
          records.delete(dead[i]);
          const emitter = dead[i].emitterRef.deref();
          if (emitter !== undefined) {
            const set = byEmitter.get(emitter);
            if (set !== undefined) set.delete(dead[i]);
          }
        }
      }
      return findings;
    },

    /**
     * Live tracked listeners. Read by snapshot(); each is one (emitter, event,
     * listener) triple still attached and not yet reaped.
     */
    count: function () {
      return records.size;
    },

    advise(finding) {
      if (finding === null || finding.kind !== KIND) return null;
      switch (finding.reason) {
        case 'owner-disposed-listener-live':
          return 'A listener on event "' + finding.event + '" was added inside an owner ' +
            'that has since been disposed, but the listener is still attached to a live ' +
            'emitter. Node keeps it -- and everything its closure captures -- forever. ' +
            'Add it inside an effect() so onCleanup removes it on disposal, or call ' +
            'emitter.removeListener() in your own teardown. This is the leak Node\'s ' +
            'MaxListenersExceededWarning misses when you stay under the threshold.';
        case 'no-owner-add':
          return 'A listener on event "' + finding.event + '" was added outside any owner. ' +
            'In Node this is often fine (the runtime does it constantly), which is why it ' +
            'is only warned about when you opt in. If this listener is meant to be scoped, ' +
            'add it inside an effect() so it is removed automatically.';
        case 'patch-double-install':
          return 'EventEmitter.prototype is patched by two kernel instances at once, so ' +
            'every listener is counted twice. Register emitter-orphan on a single tracker.';
        case 'patch-layered':
          return 'Another library wrapped EventEmitter.prototype after this kernel; its ' +
            'wrapper was left in place. Uninstall in reverse order of installation.';
        default:
          return null;
      }
    },
  };

  return kernel;
}
